body.usercss:

.client-manager-colorpicker input,
.dhxform_obj_material div.readonly.client-manager-colorpicker-view input.dhxform_textarea{
    cursor: pointer;
}

.client-manager-file-attach-view .dhxform_control,
.client-manager-icon-view .dhxform_control {

}

.client-manager-file-attach-view .dhxform_container,
.client-manager-icon-view .dhxform_container {
    border: 1px solid #dddddd;
    border-radius: 5px;
    height: calc(100% - 2px);
    width: calc(100% - 2px);
    cursor: pointer;
    background-size: contain;
    background-position: center;
    background-repeat: no-repeat;
}

.client-manager-textarea .dhxform_control {
	height: 60px;
}

userscript.var:

(function() {
    var v = new SepoaDhtmlXVaultObject({
        container: document.createElement('div'),
        type: "CBO",
        callback: function(data) {
            if (data.uploaded) {
                for (var e in this.file_data) {
                    if (this.file_data[e].state == "added") {
                        return;
                    }
                }
                var t = (SUX.getModuleTop().Sepoa.request.isPopup) ? SUX.getModuleTop().selfObj : SUX.root;
                var w = (SUX.getModuleTop().Sepoa.request.isPopup) ? SUX.getModuleTop().parent.SUX.getModuleTop() : SUX.getModuleTop();
                if (t.progressOff)
                    t.progressOff(undefined, w);
                this._afterCallback.fn(data);
                this.setAttachKey();
            }
        }
    });
    v.attachEvent('onBeforeFileAdd', function(file) {
        var allowExtension = ['JPG', 'JPEG', 'GIF', 'PNG', 'BMP'];
        var extension = file.name.substring(file.name.lastIndexOf('.') + 1, file.name.length).toUpperCase();
        if (allowExtension.indexOf(extension) + 1) {
            return true;
        } else {
            Alert(Sepoa.cache.text.get('AD_404.MESSAGE0001'));
            return false;
        }
    });
    v.attachEvent('onUploadFail', function(e, a) {
        var t = (SUX.getModuleTop().Sepoa.request.isPopup) ? SUX.getModuleTop().selfObj : SUX.root;
        var w = (SUX.getModuleTop().Sepoa.request.isPopup) ? SUX.getModuleTop().parent.SUX.getModuleTop() : SUX.getModuleTop();
        if (t.progressOff)
            t.progressOff(undefined, w);
    })
    v.f.onchange = function() {
        v._parseFilesInInput(this.files);
        if (window.dhx4.isOpera || window.dhx4.isIE10) {
            v._addFileInput()
        } else {
            this.value = ""
        }
        var t = (SUX.getModuleTop().Sepoa.request.isPopup) ? SUX.getModuleTop().selfObj : SUX.root;
        var w = (SUX.getModuleTop().Sepoa.request.isPopup) ? SUX.getModuleTop().parent.SUX.getModuleTop() : SUX.getModuleTop();
        if (t.progressOn)
            t.progressOn(w);
    }
    v.conf.orgUrl = v.conf.url
    return v;
})()


