userscript.function:

for (var i in $options) {
    var tabOptions = $options[i];
    tabbarObj.addTab(tabOptions.id, Sepoa.cache.text.get('AD_404.' + tabOptions.id));
    if (i == 0) {
        tabbarObj.tabs(tabOptions.id).setActive();
    }

    if (tabOptions.items) {
        var formOptions = [{
                type: "settings",
                position: "label-top",
                inputWidth: 120
            },
            {
                type: "block",
                width: "auto",
                list: tabOptions.items
            }
        ]

        for (var i in tabOptions.items) {
            formOptionBuilder(tabOptions.items[i]);
        }

        var formObj = tabbarObj.tabs(tabOptions.id).attachForm(formOptions);
        formObj.attachEvent('onChange', onChange);
        formObj.base[0].addEventListener('click', onItemClick.bind(formObj));
    }
}
onLoadEnd();


            if (item.type != "block" && item.name && !item.label) {
                item.label = Sepoa.cache.text.get('AD_404.' + item.name);
            }

            if (item.type == "block" || item.type == "fieldset") {
                item.width = 'auto';
                if (item.list) {
                    for (var i in item.list) {
                        formOptionBuilder(item.list[i]);
                    }
                }
            } else if (item.type == "s-colorpicker") {
                item.type="block";
                item.width="auto";
                item.list=[
                    {
                        name: item.name + "_VIEW",
                        label: item.label,
                        className: "client-manager-colorpicker-view",
                        type: "input",
                        inputWidth: 32,
                        readonly:true
                    },
                    {type:"newcolumn"},
                    {
                        name: item.name,
                        type: "colorpicker",
                        label:"#NO_LABEL#",
                        className: "client-manager-colorpicker",
                        labelWidth:88,
                        inputWidth: 88,
                        offsetTop:34,
                        offsetLeft:0,
                        readonly:true
                    }
                ]
                delete item.name;
                delete item.label;
            } else if(item.type == 's-font') {
            	item.type = 'block',
            	item.width = 'auto',
            	item.list = [
            		{
            			name: item.name + '_FONT_SIZE',
            			type: 'input',
            			label: Sepoa.cache.text.get('AD_404.FONT_SIZE')
            		},
            		{
            			name: item.name + '_FONT_WEIGHT',
            			type: 'input',
            			label: Sepoa.cache.text.get('AD_404.FONT_WEIGHT')
            		},
            		{
            			name: item.name + '_FONT_STYLE',
            			type: 'select',
            			options: [{
                                text: "",
                                value: ""
                            },
                            {
                                text: "Underline",
                                value: "underline"
                            },
                            {
                                text: "Italic",
                                value: "italic"
                            }
                        ],
            			label: Sepoa.cache.text.get('AD_404.FONT_STYLE')
            		}
            	]

            	delete item.name;
            } else if (item.type == "fileattach") {
            	var fill = (item.className == 'fill-background') ? item.className : '';
            	delete item.className;

                item.type = "block";
                item.width = "auto";
                item.list = [{
                        name: item.name + "_VIEW",
                        type: "container",
                        label: item.label?((item.label.indexOf('Has not found text') == 0)?undefined:item.label):undefined, 
                        className: "client-manager-file-attach-view " + fill,
                        inputWidth: 256,
                        inputHeight: 60
                    },
                    {
                        name: item.name,
                        className: "client-manager-file-attach-input",
                        type: "input",
                        hidden: true
                    }
                ]
                delete item.name;
            } else if (item.type == "button"){
                var style = item.name.replace(/^BUTTON_/,'');
                item.type = "fieldset";
                item.inputWidth = "auto";
                item.list = [{
                        type: 's-colorpicker',
                        name:item.name+'_COLOR',
                        label:Sepoa.cache.text.get('AD_404.BUTTON_COLOR')
                    },
                    {
                        type: 's-colorpicker',
                        name:item.name+'_HOVER_COLOR',
                        label:Sepoa.cache.text.get('AD_404.BUTTON_HOVER_COLOR')
                    },
                    {
                        type: 's-colorpicker',
                        name:item.name+'_ACTIVE_COLOR',
                        label:Sepoa.cache.text.get('AD_404.BUTTON_ACTIVE_COLOR')
                    },
                    {type:'newcolumn'},
                    {
                        type: 's-colorpicker',
                        name:item.name+'_TEXT_COLOR',
                        label:Sepoa.cache.text.get('AD_404.BUTTON_TEXT_COLOR')
                    },
                    {
                        type: 's-colorpicker',
                        name:item.name+'_HOVER_TEXT_COLOR',
