                    },
                    {
                        type: 's-colorpicker',
                        name:item.name+'_ACTIVE_BORDER_COLOR',
                        label:Sepoa.cache.text.get('AD_404.BUTTON_ACTIVE_BORDER_COLOR')
                    },
                    {type:'newcolumn'}
                ]
                if(style != 'ICON'){
                    item.list = item.list.concat([
                    {
                        name:item.name+'_ICON_BLOCK',
                        type:"block",
                        width:"auto",
                        list:[
                            //{
                            //    name: item.name+'_ICON_VIEW',
                            //    label: Sepoa.cache.text.get('AD_404.BUTTON_ICON_VIEW'),
                            //    type: "container",
                            //    className: "client-manager-icon-view" 
                            //},
                            {
                                name: item.name+'_ICON',
                                label: 'ICON',
                                className: "client-manager-icon-input",
                                type: "input",
                            //    hidden: true
                            }
                        ]
                    },
                    {
                        type:'select',
                        name:item.name+'_POSITION',
                        label:Sepoa.cache.text.get('AD_404.BUTTON_POSITION'),
                        options:[
                            {
                                text:"",
                                value:""
                            },
                            {
                                text:"icon-left",
                                value:"left"
                            },
                            {
                                text:"icon-right",
                                value:"right"
                            }
                        ]
                    }])
                }
            } else if(item.type == 'textarea') {
            	item.type = 'input'
            	item.className = 'client-manager-textarea';
            	item.rows = 1;
            } else if(item.type == 'gridcelltype'){
                item.type = 'fieldset';
                item.inputWidth = "auto";
                item.list=[
                    {
                        type: 's-colorpicker',
                        name:item.name+"_COLOR",
                        label:Sepoa.cache.text.get('AD_404.GRID_CELL_TYPE_COLOR'),
                    },
                    {
                        type: 's-colorpicker',
                        name:item.name+"_TEXT_COLOR",
                        label:Sepoa.cache.text.get('AD_404.GRID_CELL_TYPE_TEXT_COLOR'),
                    }
                ]
            } else if(item.type == 's-style') {
            	item.type = 'fieldset';
            	item.inputWidth = 'auto';

            	var list = [];
            	if(item.className == 'grid_cell_type') {
            		list.push(
            			{
	                        'type': 's-colorpicker',
	                        'name':item.name+"_COLOR",
	                        'label':Sepoa.cache.text.get('AD_404.GRID_CELL_TYPE_COLOR'),
	                    },
	                    {
	                        'type': 's-colorpicker',
	                        'name':item.name+"_TEXT_COLOR",
	                        'label':Sepoa.cache.text.get('AD_404.GRID_CELL_TYPE_TEXT_COLOR'),
	                    }
            		);
            	} else {
            		list.push(
            			{
            				'type': 's-colorpicker',
		            		'name': item.name+'_TEXT_COLOR',
		            		'label': Sepoa.cache.text.get('AD_404.SEPOA_STYLE_TEXT_COLOR')
            			}
            		);
            	}

            	list.push({'type': 's-font', 'name': item.name});

            	item.list = list;
            	delete item.className;
            } else if(item.type == 'guidesubitem') {
            	var key = item.name.split('_')[0];
            	var seq = item.name.split('_')[1];
            	var width = item.inputWidth || '';
            	item.type = 'fieldset';
                item.inputWidth = "auto";
                item.list=[
                    {
                        type: 'fileattach',
                        name:key + '_SUB_ITEM_' + seq,
                        label:Sepoa.cache.text.get('AD_404.GUIDE_SUB_ITEM_VIEW')
                    },
                    {
                        type: 'input',
                        name:key + '_SUB_ITEM_' + seq + '_LABEL',
                        label:Sepoa.cache.text.get('AD_404.GUIDE_SUB_ITEM_LABEL'),
                        inputWidth: width
                    },
                    {
                    	type: 'input',
                    	name:key + '_SUB_ITEM_' + seq + '_LINK',
                    	label:Sepoa.cache.text.get('AD_404.GUIDE_SUB_ITEM_LINK'),
                    	inputWidth: width
                    }
                ]
            }

            if(item.list){
                for (var i in item.list) {
                    formOptionBuilder(item.list[i]);
                }
            }


if (e.srcElement.classList.contains('dhxform_container')) {
    if ($(e.srcElement).parents('.client-manager-file-attach-view').length > 0) {
        var id = e.srcElement.name;
        var item = id.replace(/_VIEW$/, '');
        var attachKey = ['D',dataOutput.getValue("CLIENT_CODE"),item].join("").replaceAll("_", "").toUpperCase();
        $vault.conf.url = $vault.conf.orgUrl + '?HOUSE_CODE=' + dataOutput.getValue("CLIENT_CODE");
        $vault.setAttachKey(attachKey);
        $vault._afterCallback = {
            form: this,
            item: item,
            fn: _afterCallback = function(data) {
                var newImage = $vault.getAttachKey() + ":" + data.serverName;
                $vault._afterCallback.form.setItemValue(item, newImage);
                $vault._afterCallback.form.callEvent('onChange', [item, newImage])
                $vault._afterCallback = {};
            }
        }
        $vault.buttons.browse.click();
    }
}


            var type = this.getItemType(id);
            if (type == 'colorpicker') {
                var input = this.getInput(id+"_VIEW");
                var v = value || this.getItemValue(id);;
                input.style.backgroundColor = v;
                if(v != "#ffffff"){
                    input.style.borderColor = v;
                }
            } else if (type == "input") {
                if ($(this.getInput(id)).parents('.client-manager-file-attach-input').length > 0) {
                    var sv = (value || "").split(":");
                    if (sv.length == 2) {
                    	this.getContainer(id + "_VIEW").style.backgroundImage = sUtils.string.dataReplacer('url("$CONFIG{CONTEXT_NAME}/SepoaImage.sux?attach_key=$.{KEY}&attach_seq=$.{SEQ}&HOUSE_CODE=$.{HOUSE_CODE}")', {
                            KEY: sv[0],
                            SEQ: sv[1],
                            HOUSE_CODE: sv[0].replace(/[^D0-9]+/, '').replace('D', '') || dataOutput.getValue('CLIENT_CODE')
                        })
                    } else {
                        this.getContainer(id + "_VIEW").style.backgroundImage = "";
                    }
                }else if (id == 'GUIDE_ITEM_COUNT'){
                    var maxCnt = value || 0;
                    var w = ['FIRST', 'SECOND', 'THIRD']

                    if($share.beforeGuideItemCount){
                        if(maxCnt < $share.beforeGuideItemCount){
                            for(var i=maxCnt ; i<$share.beforeGuideItemCount;i++){
                                this.removeItem('GUIDE_'+(w[i] || i))
                                this.removeItem('GUIDE_'+(w[i] || i)+"_COLUMN");
                            }
                            $share.beforeGuideItemCount = maxCnt;
                        }
                    }

                    for(var i=($share.beforeGuideItemCount || 0) ; i<maxCnt ; i++){
                        var newItemID = w[i] || i;
                        var newItemOptions = {
                            type: 'guidesubitem',
                            name: 'GUIDE_'+newItemID,
                            label: sUtils.cache.text.get('AD_404.GUIDE_SUB_ITEM_FIELD_LABEL') + ' ' + (parseInt(i) + 1),
                            inputWidth: 256
                        }
                        formOptionBuilder(newItemOptions)
                        this.addItem('GUIDE_AREA', newItemOptions);
                        this.addItem('GUIDE_AREA', {
                            type:'newcolumn',
                            name:'GUIDE_'+newItemID+"_COLUMN"
                        });
                    }

                    $share.beforeGuideItemCount = maxCnt;
                }
            }else if (type == 'select') {
            	if(id == 'LOGIN_DESIGN_TYPE'){
            		var hideItemArr = ['LOGIN_LOGO_VIEW', 'LOGIN_MAIN_VIEW', 'LOGIN_FORM_SUB_BUTTON_USE', 'LOGIN_FORM_SUB_BUTTON_LABEL'
            							, 'LOGIN_FORM_SUB_BUTTON_LINK', 'GUIDE_ITEM_COUNT', 'GUIDE_AREA', 'CONTACT_HEADER', 'CONTACT2_HEADER', 
            							'CONTACT2_CONTENTS'];

            		var itemForRenew = ['RIGHT_CUSTOM_PATH'];
            		if(value == '' || value == undefined || value == 'default'){
	            		hideItemArr.forEach(function(item){
	            			this.showItem(item);
	            		}, this);

	            		itemForRenew.forEach(function(item){
	            			this.hideItem(item);
	            		}, this);					
            		}else if(value == 'renew'){
	            		hideItemArr.forEach(function(item){
	            			this.hideItem(item);
	            		}, this)

	            		itemForRenew.forEach(function(item){
	            			this.showItem(item);
	            		}, this);						            		
            		}
            	}
            }


var tabs = tabbarObj.getAllTabs();
for (var i in tabs) {
    var formObj = tabbarObj.tabs(tabs[i]).dataObj;
    if (formObj) {
        formObj.forEachItem(function(id) {
            onChange.apply(formObj, [id]);
        })
    }
}


clear();

dataOutput.setValue("CLIENT_CODE", clientCode);
dataOutput.setValue("COMPANY_CODE", companyCode);

doServiceAjax('sepoa.svc.admin.AD_404', 'CONNECTION', 'doQuery', null, function(so) {
    if (so.status != 1) {
        Alert(Sepoa.cache.text.get('MESSAGE.1002'));
        return;
    }

    var sf = new SepoaFormater(so.result[0]);
    if (sf.getRowCount() > 0) {
        var tabs = tabbarObj.getAllTabs();
        for (var i in tabs) {
            var formObj = tabbarObj.tabs(tabs[i]).dataObj;
            if (formObj) {
                if(tabs[i] == 'LOGIN' && sf.getValue('GUIDE_ITEM_COUNT', 0) > 0){
                    formObj.callEvent("onChange", ['GUIDE_ITEM_COUNT', sf.getValue('GUIDE_ITEM_COUNT', 0)]);
                }

                formObj.forEachItem(function(id) {
                    var type = formObj.getItemType(id);
                    if (["block", "fieldset", "container"].indexOf(type) < 0) {
                        var value = sf.getValue(id, 0);
                        if (value) {
                            formObj.setItemValue(id, value);
                            formObj.callEvent("onChange", [id, value]);
                        }
                    }
                })
            }
        }

        var basicColor = sf.getValue('BASIC_COLOR', 0);
        if(basicColor) {
        	var fillElement = $('.fill-background .dhxform_container');

        	for(var i = 0; i < fillElement.length; i++) {
        		fillElement[i].style.backgroundColor = basicColor;
        	}
        }
    }
})


